diff --git a/web/src/styles.css b/web/src/styles.css
index c66934e..6b32ce6 100644
--- a/web/src/styles.css
+++ b/web/src/styles.css
@@ -1031,6 +1031,73 @@ p {
   outline-offset: -2px;
 }

+/* The header actions menu is a sibling of the conversation title, so it must hold its own
+   positioning context for the dropdown it opens — nothing up the tree is positioned. */
+.session-actions {
+  position: relative;
+  flex: 0 0 auto;
+  margin-left: auto;
+}
+
+.session-actions-toggle {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 40px;
+  height: 40px;
+  border-radius: var(--radius-md);
+  color: var(--muted);
+}
+
+.session-actions-toggle:hover:not(:disabled) {
+  color: var(--text);
+  background: var(--surface-strong);
+}
+
+.session-actions-toggle[aria-expanded="true"] {
+  color: var(--primary);
+  background: var(--primary-soft);
+}
+
+.session-actions-menu {
+  position: absolute;
+  top: calc(100% + var(--space-1));
+  right: 0;
+  z-index: 20;
+  display: grid;
+  min-width: 232px;
+  gap: 2px;
+  padding: var(--space-1);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  background: var(--surface);
+  box-shadow: var(--shadow-lg);
+}
+
+.session-actions-menu button {
+  width: 100%;
+  min-height: 36px;
+  padding: 0 var(--space-3);
+  border: 0;
+  border-radius: var(--radius-sm);
+  background: transparent;
+  color: var(--text);
+  justify-content: flex-start;
+  text-align: left;
+}
+
+@media (hover: hover) {
+  .session-actions-menu button:hover {
+    background: var(--surface-strong);
+  }
+}
+
+.session-actions-menu button:focus-visible {
+  background: var(--surface-strong);
+  outline: 2px solid var(--primary);
+  outline-offset: -2px;
+}
+
 .message-context-menu--touch {
   left: 50%;
   bottom: max(var(--space-4), env(safe-area-inset-bottom));
